double h = (b - a) / N;
double sum = f(a) + f(b);

for (int i = 1; i < N; i++) {
    double x = a + i * h;
    if (i % 2 == 1) {
        sum += 4 * f(x);
    } else {
        sum += 2 * f(x);
    }
}

return sum * h / 3.0;

